<script setup lang="ts">
import {computed,onMounted,reactive,ref} from "vue";import {useI18n} from "vue-i18n";import {useRouter} from "vue-router";import AdminLayout from "@/components/layout/AdminLayout.vue";import AppIcon from "@/components/AppIcon.vue";import AppFooter from "@/components/AppFooter.vue";import {api,type NotificationChannel,type NotificationRule,type WebhookConfig} from "@/api/client";import {useToast} from "@/composables/useToast";
const {t}=useI18n(),router=useRouter(),{notify}=useToast(),loading=ref(true),error=ref(""),tab=ref<"channels"|"rules"|"history">("channels"),channels=ref<NotificationChannel[]>([]),rules=ref<NotificationRule[]>([]),events=ref<any[]>([]),deliveries=ref<any[]>([]),catalog=ref<any[]>([]),channelId=ref(""),ruleId=ref(""),busy=ref(false),testId=ref("");
const config=():WebhookConfig=>({provider:"dingtalk",url:"",method:"POST",headers:"{}",body:"",dingTalkSecret:"",dingTalkMessageType:"text",testBody:'{"event":"{{event}}","status":"{{status}}","message":"{{message}}"}',messageTemplate:"{{event}}\\n{{status}}\\n{{message}}",testMessageTemplate:"PacPilot test"});
const cd=reactive({name:"",enabled:true,config:config()}),rd=reactive({name:"",enabled:true,eventType:"task.execution" as NotificationRule["eventType"],phase:"finished" as NotificationRule["phase"],outcome:"failure" as NotificationRule["outcome"],channelIds:[] as string[],subjectType:""});
const phases=computed(()=>catalog.value.find(x=>x.type===rd.eventType)?.phases??[]),outcomes=computed(()=>catalog.value.find(x=>x.type===rd.eventType)?.outcomes??[]),eventName=(v:string)=>catalog.value.find(x=>x.type===v)?.label??v,phaseName=(v:string)=>({started:"开始时",progress:"执行中",finished:"结束时",state_changed:"状态变化时"} as Record<string,string>)[v]??v,outcomeName=(v?:string|null)=>({success:"成功",failure:"失败",cancelled:"已取消",timeout:"超时",unknown:"未知",any:"任意结果"} as Record<string,string>)[v??"any"]??"不限制",channelName=(id:string)=>channels.value.find(x=>x.id===id)?.name??id;
async function load(){loading.value=true;error.value="";try{if(!(await api.session()).loggedIn){await router.replace("/admin/login");return}const x=await api.notifications();channels.value=x.channels;rules.value=x.rules;events.value=[...x.events].reverse();deliveries.value=[...x.deliveries].reverse();catalog.value=x.eventCatalog}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{loading.value=false}}
function newChannel(){channelId.value="";Object.assign(cd,{name:"",enabled:true,config:config()})}function editChannel(c:NotificationChannel){channelId.value=c.id;Object.assign(cd,{name:c.name,enabled:c.enabled,config:{...c.config}})}
async function saveChannel(){busy.value=true;try{const p={name:cd.name,enabled:cd.enabled,config:{...cd.config}};if(channelId.value)await api.updateNotificationChannel(channelId.value,p);else await api.createNotificationChannel(p);await load();newChannel();notify("渠道已保存。","success")}catch(e){notify(e instanceof Error?e.message:String(e),"error")}finally{busy.value=false}}
async function removeChannel(c:NotificationChannel){if(!window.confirm("确定删除渠道“"+c.name+"”？"))return;try{await api.deleteNotificationChannel(c.id);await load();if(channelId.value===c.id)newChannel()}catch(e){notify(e instanceof Error?e.message:String(e),"error")}}
async function testChannel(c:NotificationChannel){testId.value=c.id;try{const x=await api.testNotificationChannel(c.id);notify(x.success?"测试通知已被目标接受。":x.message,x.success?"success":"error")}catch(e){notify(e instanceof Error?e.message:String(e),"error")}finally{testId.value=""}}
function newRule(){ruleId.value="";Object.assign(rd,{name:"",enabled:true,eventType:"task.execution",phase:"finished",outcome:"failure",channelIds:[],subjectType:""})}function editRule(r:NotificationRule){ruleId.value=r.id;Object.assign(rd,{name:r.name,enabled:r.enabled,eventType:r.eventType,phase:r.phase,outcome:r.outcome??"any",channelIds:[...r.channelIds],subjectType:r.subjectType??""})}
function setEvent(v:string){rd.eventType=v as NotificationRule["eventType"];if(!phases.value.includes(rd.phase))rd.phase=phases.value[0]??"finished";if(rd.outcome!=="any"&&!outcomes.value.includes(rd.outcome as never))rd.outcome="any"}
async function saveRule(){busy.value=true;try{const p={...rd,subjectType:rd.subjectType.trim()||undefined};if(ruleId.value)await api.updateNotificationRule(ruleId.value,p);else await api.createNotificationRule(p);await load();newRule();notify("规则已保存。","success")}catch(e){notify(e instanceof Error?e.message:String(e),"error")}finally{busy.value=false}}
async function removeRule(r:NotificationRule){if(!window.confirm("确定删除规则“"+r.name+"”？"))return;try{await api.deleteNotificationRule(r.id);await load();if(ruleId.value===r.id)newRule()}catch(e){notify(e instanceof Error?e.message:String(e),"error")}}
async function retry(id:string){try{await api.retryNotificationDelivery(id);await load();notify("已完成重新投递尝试。","success")}catch(e){notify(e instanceof Error?e.message:String(e),"error")}}
onMounted(()=>void load());
</script>
<template><AdminLayout active="notifications" :title="t('nav.notifications')" :subtitle="t('notifications.subtitle')"><main class="page">
<section v-if="loading" class="state"><span class="spinner"/>{{t("common.loading")}}</section><section v-else-if="error" class="state error"><AppIcon name="circle-alert" :size="18"/>{{error}}<button @click="load">重试</button></section><template v-else>
<header class="intro"><AppIcon name="bell-ring" :size="22"/><div><h2>事件驱动通知</h2><p>配置可复用的通知渠道，并用规则选择事件、阶段、结果与通知目标。通知规则不依赖 PAC 文件生成实现。</p></div><button @click="load"><AppIcon name="refresh-cw" :size="14"/>刷新</button></header>
<nav class="tabs"><button :class="{active:tab==='channels'}" @click="tab='channels'">通知渠道（{{channels.length}}）</button><button :class="{active:tab==='rules'}" @click="tab='rules'">通知规则（{{rules.length}}）</button><button :class="{active:tab==='history'}" @click="tab='history'">事件与投递（{{deliveries.length}}）</button></nav>
<section v-if="tab==='channels'" class="columns"><div class="panel"><header><div><h2>通知渠道</h2><p>渠道可供多条规则复用。</p></div><button class="primary" @click="newChannel">新增</button></header><p v-if="!channels.length" class="empty">尚无通知渠道。</p><article v-for="c in channels" :key="c.id" class="item"><div><b>{{c.name}}</b><p>{{c.provider==='dingtalk'?'钉钉机器人':'通用 HTTP Webhook'}} · {{c.enabled?'已启用':'已停用'}}</p><small>{{c.config.url}}</small></div><div class="actions"><button :disabled="!c.enabled||testId===c.id" @click="testChannel(c)">测试</button><button @click="editChannel(c)">编辑</button><button class="danger" @click="removeChannel(c)">删除</button></div></article></div>
<form class="panel form" @submit.prevent="saveChannel"><h2>{{channelId?'编辑渠道':'新增渠道'}}</h2><label>名称<input v-model="cd.name" required maxlength="100"/></label><label>类型<select v-model="cd.config.provider"><option value="dingtalk">钉钉机器人</option><option value="custom">通用 HTTP Webhook</option></select></label><label>Webhook URL<input v-model="cd.config.url" required placeholder="https://…"/><small v-if="channelId">敏感参数已脱敏；更换时请粘贴新的完整 URL。</small></label><template v-if="cd.config.provider==='dingtalk'"><label>加签密钥<input v-model="cd.config.dingTalkSecret" type="password" autocomplete="new-password" placeholder="留空保留已有密钥"/></label><label>消息格式<select v-model="cd.config.dingTalkMessageType"><option value="text">文本</option><option value="markdown">Markdown</option></select></label><label>消息模板<textarea v-model="cd.config.messageTemplate" rows="4" placeholder="{{event}}&#10;{{status}}&#10;{{message}}"/></label></template><template v-else><label>HTTP 方法<select v-model="cd.config.method"><option>POST</option><option>PUT</option><option>PATCH</option></select></label><label>请求头 JSON<textarea v-model="cd.config.headers" rows="3"/></label><label>请求体模板 JSON<textarea v-model="cd.config.body" rows="5" placeholder='{"event":"{{event}}","status":"{{status}}"}'/></label></template><label class="check"><input v-model="cd.enabled" type="checkbox"/>启用渠道</label><footer><button type="button" @click="newChannel">重置</button><button class="primary" :disabled="busy">{{busy?'保存中…':'保存渠道'}}</button></footer></form></section>
<section v-else-if="tab==='rules'" class="columns"><div class="panel"><header><div><h2>通知规则</h2><p>规则条件采用 AND 匹配；一个事件可触发多条规则。</p></div><button class="primary" @click="newRule">新增</button></header><p v-if="!rules.length" class="empty">尚无通知规则。</p><article v-for="r in rules" :key="r.id" class="item"><div><b>{{r.name}} · {{r.enabled?'已启用':'已停用'}}</b><p>{{eventName(r.eventType)}} · {{phaseName(r.phase)}} · {{r.phase==='started'?'开始时无最终结果':outcomeName(r.outcome)}}</p><small>通知至：{{r.channelIds.map(channelName).join('、')}}</small></div><div class="actions"><button @click="editRule(r)">编辑</button><button class="danger" @click="removeRule(r)">删除</button></div></article></div>
<form class="panel form" @submit.prevent="saveRule"><h2>{{ruleId?'编辑规则':'新增规则'}}</h2><label>规则名称<input v-model="rd.name" required maxlength="100"/></label><label>事件<select :value="rd.eventType" @change="setEvent(($event.target as HTMLSelectElement).value)"><option v-for="e in catalog" :key="e.type" :value="e.type">{{e.label}}（{{e.type}}）</option></select></label><label>触发阶段<select v-model="rd.phase"><option v-for="p in phases" :key="p" :value="p">{{phaseName(p)}}</option></select></label><label>结果条件<select v-model="rd.outcome"><option value="any">不限制结果</option><option v-for="o in outcomes" :key="o" :value="o">{{outcomeName(o)}}</option></select><small v-if="rd.phase==='started'">开始事件没有最终结果，建议选择不限制结果。</small></label><label>业务对象类型（可选）<input v-model="rd.subjectType" placeholder="例如 task"/></label><fieldset><legend>通知目标</legend><label v-for="c in channels" :key="c.id" class="check"><input v-model="rd.channelIds" type="checkbox" :value="c.id" :disabled="!c.enabled"/>{{c.name}} <small v-if="!c.enabled">（已停用）</small></label><small v-if="!channels.length">请先创建通知渠道。</small></fieldset><label class="check"><input v-model="rd.enabled" type="checkbox"/>启用规则</label><footer><button type="button" @click="newRule">重置</button><button class="primary" :disabled="busy||!channels.length">{{busy?'保存中…':'保存规则'}}</button></footer></form></section>
<section v-else class="panel"><h2>事件记录</h2><p>事件表达业务事实，投递记录追踪发送状态。</p><p v-if="!events.length" class="empty">暂无事件。</p><article v-for="e in events" :key="e.id" class="history"><b>{{eventName(e.type)}} · {{phaseName(e.phase)}} · {{outcomeName(e.outcome)}}</b><p>{{e.summary||e.type}}</p><small>{{e.occurredAt}} · {{e.correlationId}}</small></article><h2 class="subhead">通知投递</h2><p v-if="!deliveries.length" class="empty">暂无投递。</p><article v-for="d in deliveries" :key="d.id" class="history"><b>{{channelName(d.channelId)}} · {{d.status}}</b><p>尝试次数：{{d.attemptCount}} {{d.lastError||''}}</p><small>{{d.updatedAt}}</small><button v-if="d.status==='failed'" @click="retry(d.id)">重试</button></article></section>
</template><AppFooter/></main></AdminLayout></template>
<style scoped>
.page{display:grid;gap:16px;min-width:0}.intro,.panel,.state{padding:18px;border:1px solid var(--line);border-radius:12px;background:var(--surface)}.intro{display:flex;align-items:center;gap:13px}.intro>div{flex:1;min-width:0}.intro h2,.panel h2{margin:0;font-size:15px}.intro p,.panel header p,.panel>p{margin:5px 0 0;color:var(--muted);font-size:12px;line-height:1.6}.tabs{display:flex;gap:5px;flex-wrap:wrap}.tabs button,.actions button,.intro button,.panel button,.state button{min-height:33px;padding:0 10px;border:1px solid var(--line);border-radius:7px;background:var(--surface);color:var(--text);font:inherit;font-size:11px;cursor:pointer}.tabs .active{background:var(--accent-soft);border-color:var(--accent);color:var(--accent)}.columns{display:grid;grid-template-columns:minmax(0,1fr) minmax(300px,.9fr);gap:16px;align-items:start}.panel{min-width:0}.panel header{display:flex;justify-content:space-between;gap:10px;margin-bottom:14px}.primary{background:var(--accent)!important;color:white!important;border-color:var(--accent)!important}.danger{color:var(--red)!important}.item{display:flex;justify-content:space-between;gap:12px;padding:13px 0;border-top:1px solid var(--line)}.item>div:first-child{min-width:0}.item b,.history b{font-size:12px;overflow-wrap:anywhere}.item p,.history p{margin:5px 0;color:var(--muted);font-size:11px;overflow-wrap:anywhere}.item small,.history small,.form small{color:var(--muted);font-size:10px;overflow-wrap:anywhere}.item small{display:block;word-break:break-all}.actions{display:flex;gap:5px;flex-wrap:wrap;align-content:flex-start}.form{display:grid;gap:12px}.form label{display:grid;gap:6px;font-size:12px;font-weight:650}.form input:not([type=checkbox]),.form select,.form textarea{box-sizing:border-box;width:100%;min-width:0;padding:9px;border:1px solid var(--line);border-radius:7px;background:var(--bg);color:var(--text);font:inherit;font-size:12px;font-weight:400}.form textarea{font-family:var(--font-mono)}.form .check{display:flex;align-items:center;gap:8px}.form input[type=checkbox]{accent-color:var(--accent)}fieldset{display:grid;gap:9px;border:1px solid var(--line);border-radius:8px;padding:12px}legend{font-size:11px;font-weight:700}.form footer{display:flex;justify-content:flex-end;gap:8px}.empty{padding:20px;text-align:center;border:1px dashed var(--line);border-radius:8px;color:var(--muted);font-size:12px}.history{padding:13px 0;border-top:1px solid var(--line)}.subhead{margin-top:24px!important}.state{display:flex;align-items:center;gap:12px}.error{color:var(--red)}.spinner{width:18px;height:18px;border:2px solid var(--line);border-top-color:var(--accent);border-radius:50%;animation:spin .8s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}button:disabled{opacity:.55;cursor:not-allowed}@media(max-width:900px){.columns{grid-template-columns:1fr}.columns>.form{order:-1}}@media(max-width:600px){.item{flex-direction:column}.intro{align-items:flex-start;flex-wrap:wrap}}
</style>